import DriveAssignmentField from './DriveAssignmentField'
import TruncatedText from '../TruncatedText'
import FileList from './FileList'
import { LocalFile, LocalFileGroup, flattenFiles } from './useFileTree'
import { DriveAssignment, DriveAssignmentsHandle, PickerTarget } from './useDriveAssignments'
import * as uploadQueue from './uploadQueue'
import { OpenDriveFolder } from '../../../wailsjs/go/main/App'
import { handlePromiseRejection } from '../../lib/globalErrorHandler'
import styles from './GroupNode.module.css'

const INDENT_PER_LEVEL = 16

interface Props {
  group: LocalFileGroup
  groupKey: string
  collapsedGroups: Set<string>
  onToggle: (groupKey: string) => void
  assignments: DriveAssignmentsHandle
  inheritedAssignment: DriveAssignment | null
  onPick: (target: PickerTarget) => void
  selectedPath: string | null
  onSelectFile: (file: LocalFile) => void
}

export default function GroupNode({ group, groupKey, collapsedGroups, onToggle, assignments, inheritedAssignment, onPick, selectedPath, onSelectFile }: Props) {
  const expanded = !collapsedGroups.has(groupKey)
  const own = assignments.groupAssignments.get(groupKey) ?? null
  const effective = own ?? inheritedAssignment

  const groupFiles = flattenFiles(group)
  const allUploaded = groupFiles.length > 0 && groupFiles.every(f => uploadQueue.getStatus(f.path)?.status === 'done')

  return (
    <Box>
      <Group gap={8} wrap="nowrap" align="center">
        <button
          type="button"
          onClick={() => onToggle(groupKey)}
          aria-expanded={expanded}
          className={styles.toggle}
        >
          <Text size="xs" c="dimmed" className={styles.chevron}>{expanded ? '▼' : '▶'}</Text>
          <TruncatedText label={group.name} size="sm" fw={600}>📁 {group.name}</TruncatedText>
        </button>
        <DriveAssignmentField
          label={group.name}
          assignment={effective}
          isOwn={own !== null}
          uploaded={allUploaded && effective !== null}
          onPick={() => onPick({ type: 'group', key: groupKey })}
          onClear={() => assignments.clearGroupAssignment(groupKey)}
          onOpen={() => effective && OpenDriveFolder(effective.driveFolderId).catch(handlePromiseRejection('Opening Drive folder failed'))}
        />
      </Group>
      {expanded && (
        <Box pl={INDENT_PER_LEVEL}>
          <FileList
            files={group.files}
            assignments={assignments}
            inheritedAssignment={effective}
            onPick={onPick}
            selectedPath={selectedPath}
            onSelectFile={onSelectFile}
          />
          {group.subgroups.length > 0 && (
            <Stack gap={8} mt={4}>
              {group.subgroups.map(sub => (
                <GroupNode
                  key={sub.name}
                  group={sub}
                  groupKey={`${groupKey}/${sub.name}`}
                  collapsedGroups={collapsedGroups}
                  onToggle={onToggle}
                  assignments={assignments}
                  inheritedAssignment={effective}
                  onPick={onPick}
                  selectedPath={selectedPath}
                  onSelectFile={onSelectFile}
                />
              ))}
            </Stack>
          )}
        </Box>
      )}
    </Box>
  )
}

import { useRef } from 'react'
import { Badge, Box, Tooltip } from '@mantine/core'
import { IconExternalLink } from '@tabler/icons-react'
import { DriveAssignment } from './useDriveAssignments'
import { useIsTruncated } from '../../lib/useIsTruncated'
import styles from './DriveAssignmentField.module.css'

interface Props {
  label: string
  assignment: DriveAssignment | null
  isOwn: boolean
  // True once every file this assignment covers has finished uploading (so
  // assignment is non-null: nothing uploads without a resolved folder). The
  // destination is locked in at that point (see uploadQueue's read-only
  // rationale), so the badge opens the folder in Drive instead of the
  // picker, and the clear control disappears.
  uploaded: boolean
  onPick: () => void
  onClear: () => void
  onOpen: () => void
}

// Pinned to the right of its row (filename or folder header) by the caller,
// so badges land at a consistent horizontal position regardless of nesting
// depth - scannable as a column rather than a per-row detail.
export default function DriveAssignmentField({ label, assignment, isOwn, uploaded, onPick, onClear, onOpen }: Props) {
  const textRef = useRef<HTMLSpanElement>(null)
  const displayPath = assignment ? assignment.path : 'Not assigned'
  const truncated = useIsTruncated(textRef, displayPath)

  const badge = (
    <Badge
      component="button"
      type="button"
      onClick={uploaded ? onOpen : onPick}
      aria-label={uploaded ? `Open Drive folder for ${label}` : `Set Drive folder for ${label}`}
      color={assignment ? 'blue' : 'gray'}
      variant={isOwn ? 'light' : 'outline'}
      size="sm"
      radius="sm"
      rightSection={uploaded ? <IconExternalLink size={10} /> : undefined}
      className={`${styles.badge} ${isOwn ? styles.badgeOwn : ''}`}
      styles={{ label: { overflow: 'hidden' } }}
    >
      <span ref={textRef} className={styles.badgeText}>
        📁 {displayPath}
      </span>
    </Badge>
  )

  return (
    <Box className={styles.container}>
      {truncated ? <Tooltip label={displayPath} openDelay={500}>{badge}</Tooltip> : badge}
      {isOwn && !uploaded && (
        <button
          type="button"
          onClick={onClear}
          aria-label={`Clear Drive folder for ${label}`}
          className={styles.clearButton}
        >
          ✕
        </button>
      )}
    </Box>
  )
}

import { ActionIcon, Box, Button, Group, Loader, Modal, Stack, Text } from '@mantine/core'
import { IconExternalLink } from '@tabler/icons-react'
import TruncatedText from '../TruncatedText'
import { LocalFile, LocalFileGroup, flattenFiles } from './useFileTree'
import * as uploadQueue from './uploadQueue'
import { OpenDriveFolder } from '../../../wailsjs/go/main/App'
import { handlePromiseRejection } from '../../lib/globalErrorHandler'
import styles from './UploadModal.module.css'

interface Props {
  opened: boolean
  tree: LocalFileGroup
  onClose: () => void
}

// Per-file status lives in the uploadQueue module singleton, not in this
// component's state — it re-renders by subscribing, the same pattern
// lib/pageCache's consumers use.
export default function UploadModal({ opened, tree, onClose }: Props) {
  uploadQueue.useUploadQueueRender()

  const paths = flattenFiles(tree).map(f => f.path)
  const settled = uploadQueue.hasSettled(paths)
  const canResume = settled && uploadQueue.hasPaused(paths)

  return (
    <Modal
      opened={opened}
      onClose={onClose}
      title="Uploading to Drive"
      closeOnClickOutside={false}
      closeOnEscape={false}
      withCloseButton={false}
      size="md"
    >
      <Stack gap="md">
        <Stack gap={10}>
          {tree.files.map(file => <FileRow key={file.path} file={file} />)}
          {tree.subgroups.map(group => (
            <GroupSection key={group.name} group={group} groupKey={group.name} />
          ))}
        </Stack>
        <Group justify="flex-end">
          <Button
            variant="default"
            disabled={settled && !canResume}
            onClick={() => (canResume ? uploadQueue.resumePaused(paths) : uploadQueue.cancelAll())}
          >
            {canResume ? 'Resume' : 'Cancel'}
          </Button>
          <Button disabled={!settled} onClick={onClose}>
            Close
          </Button>
        </Group>
      </Stack>
    </Modal>
  )
}

function GroupSection({ group, groupKey }: { group: LocalFileGroup; groupKey: string }) {
  const groupFiles = flattenFiles(group)
  const doneCount = groupFiles.filter(f => uploadQueue.getStatus(f.path)?.status === 'done').length

  return (
    <Box pl={12}>
      <Group justify="space-between" gap={8} mb={4} wrap="nowrap">
        <TruncatedText label={group.name} size="sm" fw={600}>📁 {group.name}</TruncatedText>
        <Text size="xs" c="dimmed" className={styles.groupCount}>{doneCount}/{groupFiles.length}</Text>
      </Group>
      <Stack gap={10}>
        {group.files.map(file => <FileRow key={file.path} file={file} />)}
        {group.subgroups.map(sub => (
          <GroupSection key={sub.name} group={sub} groupKey={`${groupKey}/${sub.name}`} />
        ))}
      </Stack>
    </Box>
  )
}

function FileRow({ file }: { file: LocalFile }) {
  const entry = uploadQueue.getStatus(file.path)
  const status = entry?.status

  return (
    <Group justify="space-between" wrap="nowrap" gap={8}>
      <TruncatedText label={file.name} size="sm" className={styles.fileName}>{file.name}</TruncatedText>
      {status === 'queued' && <Text size="sm" c="dimmed">Queued</Text>}
      {status === 'uploading' && (
        <Group gap={6} wrap="nowrap">
          <Loader size="xs" />
          <Text size="sm" c="dimmed">Uploading…</Text>
        </Group>
      )}
      {status === 'done' && <Text size="sm" c="green">✓ Uploaded</Text>}
      {(status === undefined || status === 'paused') && <Text size="sm" c="dimmed">Not uploaded</Text>}
      {status === 'cancelled' && (
        <Group gap={8} wrap="nowrap">
          <Text size="sm" c="dimmed">Cancelled</Text>
          <Button size="xs" variant="default" onClick={() => uploadQueue.retry(entry!)}>
            Retry
          </Button>
        </Group>
      )}
      {status === 'error' && (
        <Group gap={8} wrap="nowrap">
          <TruncatedText label={entry?.error ?? ''} size="sm" c="red" className={styles.errorText}>
            ⚠ {entry?.error}
          </TruncatedText>
          <Button size="xs" variant="default" onClick={() => uploadQueue.retry(entry!)}>
            Retry
          </Button>
        </Group>
      )}
      {entry && (
        <ActionIcon
          variant="subtle"
          size="sm"
          aria-label={`Open destination Drive folder for ${file.name}`}
          onClick={() => OpenDriveFolder(entry.folderId).catch(handlePromiseRejection('Opening Drive folder failed'))}
        >
          <IconExternalLink size={14} />
        </ActionIcon>
      )}
    </Group>
  )
}

import { useState, useCallback } from 'react'
import { PickFolder, ScanLocalRoot } from '../../../wailsjs/go/main/App'

export interface LocalFile {
  path: string
  name: string
  sizeBytes: number
  isPdf: boolean
  pageCount: number
  corrupt: boolean
}

export interface LocalFileGroup {
  name: string
  files: LocalFile[]
  subgroups: LocalFileGroup[]
}

// Flat, ordered list of every file in the tree (a group's own files, then
// its subgroups' files, recursively). Shared by the upload worker (order to
// process files in), the upload modal's per-group rollup counts, and the
// "every file in this group is done" check driving the Open-in-Drive link —
// one traversal so they can't drift out of sync on how they handle nesting.
export function flattenFiles(group: LocalFileGroup): LocalFile[] {
  return [...group.files, ...group.subgroups.flatMap(flattenFiles)]
}

export interface FileTreeHandle {
  root: string | null
  tree: LocalFileGroup | null
  loading: boolean
  error: string | null
  pickRoot: () => Promise<void>
}

export function useFileTree(): FileTreeHandle {
  const [root, setRoot] = useState<string | null>(null)
  const [tree, setTree] = useState<LocalFileGroup | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const pickRoot = useCallback(async () => {
    const folder = await PickFolder('Choose Root Folder')
    if (!folder) return

    setRoot(folder)
    setLoading(true)
    setError(null)
    try {
      setTree(await ScanLocalRoot(folder))
    } catch (e) {
      setTree(null)
      setError(String(e))
    } finally {
      setLoading(false)
    }
  }, [])

  return { root, tree, loading, error, pickRoot }
}

import { useState, useCallback } from 'react'
import { LocalFileGroup } from './useFileTree'

export interface DriveAssignment {
  driveFolderId: string
  path: string
}

// Identifies what a picked Drive folder should be applied to: a subfolder
// group (by its path key) or an individual file (by its filesystem path).
export type PickerTarget = { type: 'group'; key: string } | { type: 'file'; path: string }

export interface DriveAssignmentsHandle {
  groupAssignments: Map<string, DriveAssignment>
  fileOverrides: Map<string, DriveAssignment>
  setGroupAssignment: (groupKey: string, assignment: DriveAssignment) => void
  clearGroupAssignment: (groupKey: string) => void
  setFileOverride: (filePath: string, assignment: DriveAssignment) => void
  clearFileOverride: (filePath: string) => void
}

// Tracks Drive folder assignments made directly on a subfolder group or on
// an individual file (a file-level assignment overrides its group's).
// Resolving the *effective* assignment for a given group/file (own, else
// inherited from the nearest ancestor group, else none) is the caller's
// job, since only the caller knows the tree structure to walk.
export function useDriveAssignments(): DriveAssignmentsHandle {
  const [groupAssignments, setGroupAssignments] = useState<Map<string, DriveAssignment>>(new Map())
  const [fileOverrides, setFileOverrides] = useState<Map<string, DriveAssignment>>(new Map())

  const setGroupAssignment = useCallback((groupKey: string, assignment: DriveAssignment) => {
    setGroupAssignments(prev => new Map(prev).set(groupKey, assignment))
  }, [])

  const clearGroupAssignment = useCallback((groupKey: string) => {
    setGroupAssignments(prev => {
      const next = new Map(prev)
      next.delete(groupKey)
      return next
    })
  }, [])

  const setFileOverride = useCallback((filePath: string, assignment: DriveAssignment) => {
    setFileOverrides(prev => new Map(prev).set(filePath, assignment))
  }, [])

  const clearFileOverride = useCallback((filePath: string) => {
    setFileOverrides(prev => {
      const next = new Map(prev)
      next.delete(filePath)
      return next
    })
  }, [])

  return { groupAssignments, fileOverrides, setGroupAssignment, clearGroupAssignment, setFileOverride, clearFileOverride }
}

// Effective Drive assignment for every file in the tree: its own override,
// else the nearest ancestor group's assignment, else null. Mirrors the
// inheritance walk GroupNode/FileList do inline during render (same
// groupKey scheme: joined by '/', rooted at each top-level subgroup's own
// name), but usable outside a render tree — e.g. to check whether every
// file is ready to upload, or to build an upload job list.
export function resolveEffectiveAssignments(
  tree: LocalFileGroup,
  { groupAssignments, fileOverrides }: Pick<DriveAssignmentsHandle, 'groupAssignments' | 'fileOverrides'>
): Map<string, DriveAssignment | null> {
  const result = new Map<string, DriveAssignment | null>()

  const walk = (group: LocalFileGroup, groupKey: string | null, inherited: DriveAssignment | null) => {
    const effective = (groupKey !== null ? groupAssignments.get(groupKey) : undefined) ?? inherited
    for (const file of group.files) {
      result.set(file.path, fileOverrides.get(file.path) ?? effective)
    }
    for (const sub of group.subgroups) {
      walk(sub, groupKey !== null ? `${groupKey}/${sub.name}` : sub.name, effective)
    }
  }
  walk(tree, null, null)

  return result
}

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
