input.new_string:
interface Props {
  files: LocalFile[]
  assignments: DriveAssignmentsHandle
  inheritedAssignment: DriveAssignment | null
  locked: boolean
  onPick: (target: PickerTarget) => void
  selectedPath: string | null
  onSelectFile: (file: LocalFile) => void
}

// Terminal (settled) statuses that warrant a badge next to a file's
// size/page-count line once a run has touched it. 'done' reads as success;
// anything else settled without succeeding (error, or aborted mid-upload)
// reads as a warning. 'queued'/'uploading'/'paused' aren't terminal — the
// tree is locked and non-interactive for the run's duration, and a paused
// file was never actually attempted, so neither gets a badge here.
function terminalBadge(status: uploadQueue.UploadStatus | undefined, error: string | undefined) {
  if (status === 'done') return { icon: '✓', color: 'green', tooltip: 'Uploaded' }
  if (status === 'error') return { icon: '⚠', color: 'red', tooltip: error ?? 'Upload failed' }
  if (status === 'cancelled') return { icon: '⚠', color: 'red', tooltip: 'Cancelled' }
