const assignments = useDriveAssignments()
const [pickerTarget, setPickerTarget] = useState<PickerTarget | null>(null)
const handlePicked = (folder: DriveAssignment) => {
  if (pickerTarget?.type === 'group') assignments.setGroupAssignment(pickerTarget.key, folder)
  else if (pickerTarget?.type === 'file') assignments.setFileOverride(pickerTarget.path, folder)
  setPickerTarget(null)
}

const [uploadModalOpen, setUploadModalOpen] = useState(false)
const allFiles = tree ? flattenFiles(tree) : []
const effectiveAssignments = tree ? resolveEffectiveAssignments(tree, assignments) : null
const readyToUpload = allFiles.length > 0 && allFiles.every(f => effectiveAssignments!.get(f.path) != null)

// Once any file in the tree has been touched by a run, the whole tree
// locks (see DriveAssignmentField's `locked` prop) and "Upload All" turns
// into the retry/all-done state below. Files still 'paused' (queued but
// never started, left over from a Cancel) count as needing a retry too.
const locked = allFiles.some(f => uploadQueue.getStatus(f.path) != null)
const filesNeedingRetry = allFiles.filter(f => {
  const status = uploadQueue.getStatus(f.path)?.status
  return status === 'error' || status === 'cancelled' || status === 'paused'
})
const allUploaded = locked && filesNeedingRetry.length === 0

const buildJob = (f: LocalFile): uploadQueue.UploadJob => {
  const assignment = effectiveAssignments!.get(f.path)
  // Upload All is disabled until readyToUpload is true, and a retry only
  // ever re-targets a file that already resolved once, so every file
  // should resolve here — this is a defensive check against those guards
  // drifting out of sync, not an expected path.
  if (!assignment) throw new Error(`No Drive folder assigned for "${f.path}"`)
  return { path: f.path, folderId: assignment.driveFolderId, name: f.name }
}
const handleUploadAll = () => {
  if (!tree || !effectiveAssignments) return
  uploadQueue.start(allFiles.map(buildJob))
  setUploadModalOpen(true)
}
const handleRetryFailed = () => {
  if (!tree || !effectiveAssignments) return
  uploadQueue.start(filesNeedingRetry.map(buildJob))
  setUploadModalOpen(true)
}
const handlePickRoot = async () => {
  // A new root discards the old tree's upload-queue state along with it —
  // picking a new root is the only way out of the read-only lock.
  if (await pickRoot()) uploadQueue.reset()
}

return (
  <Box className={styles.root}>
    <Toolbar>
      <Button size="xs" variant="default" onClick={handlePickRoot}>
        {root ? ellipsisPath(root) : 'Choose root folder…'}
      </Button>
      <Box className={styles.toolbarSpacer} />
      <Tooltip
        label={tree ? 'Every file needs a Drive folder before uploading' : 'Choose a root folder first'}
        disabled={locked || readyToUpload}
      >
        <span>
          {locked ? (
            <Button size="xs" disabled={allUploaded} onClick={handleRetryFailed}>
              {allUploaded ? 'All Uploaded' : `Retry Failed (${filesNeedingRetry.length})`}
            </Button>
          ) : (
            <Button size="xs" disabled={!readyToUpload} onClick={handleUploadAll}>
              Upload All
            </Button>
          )}
        </span>
      </Tooltip>
    </Toolbar>

    <Box className={styles.body}>

