  it('locks the tree and shows terminal badges once a run finishes, and "Upload All" becomes "All Uploaded"', async () => {
    await setupWithTree()
    await assignAllFolders()
    vi.mocked(UploadFile).mockResolvedValue('drive-id')

    fireEvent.click(screen.getByRole('button', { name: 'Upload All' }))
    await waitFor(() => expect(screen.getAllByText('✓ Uploaded').length).toBe(3))
    fireEvent.click(screen.getByRole('button', { name: 'Close' }))

    expect(screen.getAllByText('✓').length).toBe(3) // terminal badge next to each file's size/page-count line
    expect(isDisabled('All Uploaded')).toBe(true)

    // Locked: re-picking a Drive folder for an already-uploaded file/group is
    // disallowed (its badge switched to an Open-in-Drive link anyway), but so
    // is a file that has no group to inherit from, like "misc".
    expect((screen.getByRole('button', { name: 'Open Drive folder for misc' }) as HTMLButtonElement).disabled).toBe(false)
    expect(screen.queryByRole('button', { name: 'Clear Drive folder for misc' })).toBeNull()
  })

  it('a run finishing with a failure locks the unresolved file\'s badge and offers "Retry Failed (N)"', async () => {
    await setupWithTree()
    await assignAllFolders()
    // flattenFiles visits root files before the "invoices" subgroup, so the
    // first UploadFile call is for misc.pdf.
    vi.mocked(UploadFile).mockRejectedValueOnce(new Error('quota exceeded')).mockResolvedValue('drive-id')

    fireEvent.click(screen.getByRole('button', { name: 'Upload All' }))
    await waitFor(() => expect(screen.getByText(/quota exceeded/)).toBeTruthy())
    fireEvent.click(screen.getByRole('button', { name: 'Close' }))

    expect(screen.getAllByText('✓').length).toBe(2)
    expect(screen.getByText('⚠')).toBeTruthy()
    expect(isDisabled('Retry Failed (1)')).toBe(false)

    // misc never resolved, so its badge is still the folder picker — but
    // locked, since a run has started.
    const miscBadge = screen.getByRole('button', { name: 'Set Drive folder for misc' }) as HTMLButtonElement
    expect(miscBadge.disabled).toBe(true)
    expect(screen.queryByRole('button', { name: 'Clear Drive folder for misc' })).toBeNull()

    fireEvent.click(screen.getByRole('button', { name: 'Retry Failed (1)' }))
    expect(await screen.findByText('Uploading to Drive')).toBeTruthy()
    await waitFor(() => expect(UploadFile).toHaveBeenCalledTimes(4)) // 3 initial + 1 retry, not a full re-run
    await waitFor(() => expect(screen.getAllByText('✓ Uploaded').length).toBe(3))

    fireEvent.click(screen.getByRole('button', { name: 'Close' }))
    expect(isDisabled('All Uploaded')).toBe(true)
  })
})

